-- One quality-aware seam shared by dashboards and leaderboards. OMP storage is untouched.
create view public.collector_accounting_parts with (security_invoker=true) as select user_id,ts,observation->>'provider' as provider,observation->>'model' as model,(observation->>'is_subagent')::boolean as is_subagent,call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,
case when observation->>'is_subagent' is null then null when (observation->>'is_subagent')::boolean then total_tokens else 0 end as subagent_tokens,cost_usd,
total_tokens is null as has_unknown_tokens,cost_usd is null as has_unknown_cost,call_count is null as has_unknown_calls,
observation->>'cost_basis'='estimated' as has_estimated_cost,observation->>'quality'='reconstructed' as has_reconstructed
from public.collector_contributions where not superseded;
create view public.usage_accounting_parts with (security_invoker=true) as
select user_id,day::timestamp at time zone 'utc' as ts,provider,model,is_subagent,call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,case when is_subagent then total_tokens else 0 end as subagent_tokens,cost_usd,false as has_unknown_tokens,false as has_unknown_cost,false as has_unknown_calls,false as has_estimated_cost,false as has_reconstructed from public.usage_daily where day<(now() at time zone 'utc')::date
union all select user_id,day::timestamp at time zone 'utc' as ts,provider,model,is_subagent,call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,case when is_subagent then total_tokens else 0 end as subagent_tokens,cost_usd,false as has_unknown_tokens,false as has_unknown_cost,false as has_unknown_calls,true as has_estimated_cost,false as has_reconstructed from public.usage_history
union all select user_id,ts,provider,model,is_subagent,1::bigint as call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,case when is_subagent then total_tokens else 0 end as subagent_tokens,cost_usd,false as has_unknown_tokens,false as has_unknown_cost,false as has_unknown_calls,false as has_estimated_cost,false as has_reconstructed from public.usage_events where ts>=((now() at time zone 'utc')::date)::timestamp at time zone 'utc'
union all select * from public.collector_accounting_parts;
revoke all on public.collector_accounting_parts,public.usage_accounting_parts from public,anon,authenticated;
grant select on public.collector_accounting_parts,public.usage_accounting_parts to authenticated;
-- Keep the existing OMP daily-rollup chart semantics; collector rows are exact and durable.
create view public.usage_daily_accounting_parts with (security_invoker=true) as
select user_id,day::timestamp at time zone 'utc' as ts,provider,model,is_subagent,call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,cost_usd,false as has_unknown_tokens,false as has_unknown_cost,false as has_unknown_calls,false as has_estimated_cost,false as has_reconstructed from public.usage_daily
union all select user_id,day::timestamp at time zone 'utc' as ts,provider,model,is_subagent,call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,cost_usd,false as has_unknown_tokens,false as has_unknown_cost,false as has_unknown_calls,true as has_estimated_cost,false as has_reconstructed from public.usage_history
union all select user_id,ts,provider,model,is_subagent,call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,cost_usd,has_unknown_tokens,has_unknown_cost,has_unknown_calls,has_estimated_cost,has_reconstructed from public.collector_accounting_parts;
revoke all on public.usage_daily_accounting_parts from public,anon,authenticated;
grant select on public.usage_daily_accounting_parts to authenticated;
create or replace view public.usage_daily_all with (security_invoker=true) as
select user_id,(ts at time zone 'utc')::date as day,provider,model,is_subagent,
case when count(call_count)=count(*) then sum(call_count)::bigint end as call_count,case when count(input_tokens)=count(*) then sum(input_tokens)::bigint end as input_tokens,case when count(output_tokens)=count(*) then sum(output_tokens)::bigint end as output_tokens,case when count(cache_read_tokens)=count(*) then sum(cache_read_tokens)::bigint end as cache_read_tokens,case when count(cache_write_tokens)=count(*) then sum(cache_write_tokens)::bigint end as cache_write_tokens,case when count(total_tokens)=count(*) then sum(total_tokens)::bigint end as total_tokens,case when count(cost_usd)=count(*) then sum(cost_usd) end as cost_usd,
bool_or(has_unknown_tokens) as has_unknown_tokens,bool_or(has_unknown_cost) as has_unknown_cost,bool_or(has_unknown_calls) as has_unknown_calls,bool_or(has_estimated_cost) as has_estimated_cost,bool_or(has_reconstructed) as has_reconstructed
from public.usage_daily_accounting_parts group by 1,2,3,4,5;
drop function public.leaderboard(integer);
drop function public.leaderboard_since(timestamptz);
drop function public.leaderboard_all_time();
create function public.leaderboard_all_time() returns table(user_id uuid,call_count bigint,input_tokens bigint,output_tokens bigint,cache_read_tokens bigint,cache_write_tokens bigint,total_tokens bigint,subagent_tokens bigint,cost_usd numeric,has_unknown_tokens boolean,has_unknown_cost boolean,has_unknown_calls boolean,has_estimated_cost boolean,has_reconstructed boolean) language sql stable security invoker set search_path='' as $$
select user_id,case when count(call_count)=count(*) then sum(call_count)::bigint end as call_count,case when count(input_tokens)=count(*) then sum(input_tokens)::bigint end as input_tokens,case when count(output_tokens)=count(*) then sum(output_tokens)::bigint end as output_tokens,case when count(cache_read_tokens)=count(*) then sum(cache_read_tokens)::bigint end as cache_read_tokens,case when count(cache_write_tokens)=count(*) then sum(cache_write_tokens)::bigint end as cache_write_tokens,case when count(total_tokens)=count(*) then sum(total_tokens)::bigint end as total_tokens,case when count(subagent_tokens)=count(*) then sum(subagent_tokens)::bigint end as subagent_tokens,case when count(cost_usd)=count(*) then sum(cost_usd) end as cost_usd,bool_or(has_unknown_tokens) as has_unknown_tokens,bool_or(has_unknown_cost) as has_unknown_cost,bool_or(has_unknown_calls) as has_unknown_calls,bool_or(has_estimated_cost) as has_estimated_cost,bool_or(has_reconstructed) as has_reconstructed from public.usage_accounting_parts group by user_id;
$$;
revoke all on function public.leaderboard_all_time() from public,anon;
grant execute on function public.leaderboard_all_time() to authenticated;
create function public.leaderboard_since(p_since timestamptz) returns table(user_id uuid,call_count bigint,input_tokens bigint,output_tokens bigint,cache_read_tokens bigint,cache_write_tokens bigint,total_tokens bigint,subagent_tokens bigint,cost_usd numeric,has_unknown_tokens boolean,has_unknown_cost boolean,has_unknown_calls boolean,has_estimated_cost boolean,has_reconstructed boolean) language sql stable security invoker set search_path='' as $$
select user_id,case when count(call_count)=count(*) then sum(call_count)::bigint end as call_count,case when count(input_tokens)=count(*) then sum(input_tokens)::bigint end as input_tokens,case when count(output_tokens)=count(*) then sum(output_tokens)::bigint end as output_tokens,case when count(cache_read_tokens)=count(*) then sum(cache_read_tokens)::bigint end as cache_read_tokens,case when count(cache_write_tokens)=count(*) then sum(cache_write_tokens)::bigint end as cache_write_tokens,case when count(total_tokens)=count(*) then sum(total_tokens)::bigint end as total_tokens,case when count(subagent_tokens)=count(*) then sum(subagent_tokens)::bigint end as subagent_tokens,case when count(cost_usd)=count(*) then sum(cost_usd) end as cost_usd,bool_or(has_unknown_tokens) as has_unknown_tokens,bool_or(has_unknown_cost) as has_unknown_cost,bool_or(has_unknown_calls) as has_unknown_calls,bool_or(has_estimated_cost) as has_estimated_cost,bool_or(has_reconstructed) as has_reconstructed from (select user_id,ts,provider,model,is_subagent,1::bigint as call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,case when is_subagent then total_tokens else 0 end as subagent_tokens,cost_usd,false as has_unknown_tokens,false as has_unknown_cost,false as has_unknown_calls,false as has_estimated_cost,false as has_reconstructed from public.usage_events where ts>=greatest(p_since,now()-interval '7 days') union all select * from public.collector_accounting_parts where ts>=p_since) parts group by user_id;
$$;
revoke all on function public.leaderboard_since(timestamptz) from public,anon;
grant execute on function public.leaderboard_since(timestamptz) to authenticated;
create function public.leaderboard(p_days integer default 7) returns table(user_id uuid,call_count bigint,input_tokens bigint,output_tokens bigint,cache_read_tokens bigint,cache_write_tokens bigint,total_tokens bigint,subagent_tokens bigint,cost_usd numeric,has_unknown_tokens boolean,has_unknown_cost boolean,has_unknown_calls boolean,has_estimated_cost boolean,has_reconstructed boolean) language sql stable security invoker set search_path='' as $$
select user_id,case when count(call_count)=count(*) then sum(call_count)::bigint end as call_count,case when count(input_tokens)=count(*) then sum(input_tokens)::bigint end as input_tokens,case when count(output_tokens)=count(*) then sum(output_tokens)::bigint end as output_tokens,case when count(cache_read_tokens)=count(*) then sum(cache_read_tokens)::bigint end as cache_read_tokens,case when count(cache_write_tokens)=count(*) then sum(cache_write_tokens)::bigint end as cache_write_tokens,case when count(total_tokens)=count(*) then sum(total_tokens)::bigint end as total_tokens,case when count(subagent_tokens)=count(*) then sum(subagent_tokens)::bigint end as subagent_tokens,case when count(cost_usd)=count(*) then sum(cost_usd) end as cost_usd,bool_or(has_unknown_tokens) as has_unknown_tokens,bool_or(has_unknown_cost) as has_unknown_cost,bool_or(has_unknown_calls) as has_unknown_calls,bool_or(has_estimated_cost) as has_estimated_cost,bool_or(has_reconstructed) as has_reconstructed from (select user_id,ts,provider,model,is_subagent,1::bigint as call_count,input_tokens,output_tokens,cache_read_tokens,cache_write_tokens,total_tokens,case when is_subagent then total_tokens else 0 end as subagent_tokens,cost_usd,false as has_unknown_tokens,false as has_unknown_cost,false as has_unknown_calls,false as has_estimated_cost,false as has_reconstructed from public.usage_events where ts>=now()-make_interval(days=>least(greatest(p_days,1),7)) union all select * from public.collector_accounting_parts where ts>=now()-make_interval(days=>least(greatest(p_days,1),7))) parts group by user_id;
$$;
revoke all on function public.leaderboard(integer) from public,anon;
grant execute on function public.leaderboard(integer) to authenticated;
-- Only genuinely absent users receive zeros, never users with unavailable measurements.
create or replace function public.discord_leaderboard(p_period text default 'week')
returns table(handle text,display_name text,total_tokens bigint,subagent_tokens bigint,cost_usd numeric)
language plpgsql stable security definer set search_path='' as $$
begin
if p_period is null or p_period not in ('today','week','all') then raise exception 'invalid period' using errcode='22023'; end if;
if p_period='all' then
return query select p.handle,p.display_name,case when l.user_id is null then 0::bigint else l.total_tokens end,case when l.user_id is null then 0::bigint else l.subagent_tokens end,case when l.user_id is null then 0::numeric else l.cost_usd end from public.profiles p left join public.leaderboard_all_time() l on l.user_id=p.id;
else
return query select p.handle,p.display_name,case when l.user_id is null then 0::bigint else l.total_tokens end,case when l.user_id is null then 0::bigint else l.subagent_tokens end,case when l.user_id is null then 0::numeric else l.cost_usd end from public.profiles p left join public.leaderboard_since(case when p_period='today' then (now() at time zone 'utc')::date::timestamp at time zone 'utc' else now()-interval '7 days' end) l on l.user_id=p.id;
end if;
end;
$$;
revoke all on function public.discord_leaderboard(text) from public,anon,authenticated;
grant execute on function public.discord_leaderboard(text) to tokenmunchers_discord_reader;
